-- TouristTurkey — başlangıç verisi
-- schema.sql çalıştıktan SONRA bunu çalıştırın.





-- Önümüzdeki 60 gün için müsaitlik satırları
select p.id, d::date, p.cap, 0, false
from products p, generate_series(current_date, current_date + interval '60 days', interval '1 day') d
on conflict (product_id, date) do nothing;

